// Generated by Copilot
const { Router } = require('express')

const PLAYER_COLUMNS = `
  id,
  player_number,
  first_name,
  last_name,
  favorite_food,
  favorite_movie,
  bio,
  photo_path,
  league,
  season,
  year,
  sport
`

module.exports = function createTeamRoutes(db) {
  const router = Router()

  // GET all teams, optionally filtered by ?sport=Baseball
  router.get('/', async (req, res) => {
    try {
      const sport = req.query.sport

      let query = `
        SELECT DISTINCT league, sport
        FROM coaches
        WHERE archive = 'N'
      `
      const params = []

      if (sport) {
        query += ` AND lower(sport) = ?`
        params.push(sport.toLowerCase())
      }

      query += ` ORDER BY league`

      const rows = await db.all(query, params)
      res.json(rows)

    } catch (err) {
      console.error(err)
      res.status(500).json({ error: 'internal_error' })
    }
  })

  // GET available sports
  router.get('/sports', async (req, res) => {
    try {
      const rows = await db.all(`
        SELECT DISTINCT sport
        FROM coaches
        WHERE archive = 'N'
        ORDER BY sport
      `)
      res.json(rows.map(r => r.sport))
    } catch (err) {
      console.error(err)
      res.status(500).json({ error: 'internal_error' })
    }
  })

  // GET team details
  router.get('/:league', async (req, res) => {
    try {
      const league = req.params.league.toLowerCase()

      const coach = await db.get(`
        SELECT
          first_name,
          last_name,
          league
        FROM coaches
        WHERE lower(league) = ?
          AND archive = 'N'
        LIMIT 1
      `, league)

      const players = await db.all(`
        SELECT
          ${PLAYER_COLUMNS}
        FROM players
        WHERE lower(league) = ?
        ORDER BY player_number
      `, league)

      res.json({
        league: coach?.league ?? req.params.league,
        headCoach: coach
          ? `${coach.first_name} ${coach.last_name}`
          : null,
        players
      })

    } catch (err) {
      console.error(err)
      res.status(500).json({ error: 'internal_error' })
    }
  })

  return router
}
